    var `driveNeedsSync`: kotlin.Boolean
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAgentInfo: FfiConverterRustBuffer<AgentInfo> {
    override fun read(buf: ByteBuffer): AgentInfo {
        return AgentInfo(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterBoolean.read(buf),
        )
    }

    override fun allocationSize(value: AgentInfo) = (
            FfiConverterString.allocationSize(value.`subject`) +
            FfiConverterString.allocationSize(value.`secret`) +
            FfiConverterString.allocationSize(value.`publicKey`) +
            FfiConverterOptionalString.allocationSize(value.`name`) +
            FfiConverterBoolean.allocationSize(value.`driveNeedsSync`)
    )

    override fun write(value: AgentInfo, buf: ByteBuffer) {
            FfiConverterString.write(value.`subject`, buf)
            FfiConverterString.write(value.`secret`, buf)
            FfiConverterString.write(value.`publicKey`, buf)
            FfiConverterOptionalString.write(value.`name`, buf)
            FfiConverterBoolean.write(value.`driveNeedsSync`, buf)
    }
}



