sealed class AtomicSdkException(message: String): kotlin.Exception(message) {
        
        class Failed(message: String) : AtomicSdkException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AtomicSdkException> {
        override fun lift(error_buf: RustBuffer.ByValue): AtomicSdkException = FfiConverterTypeAtomicSdkError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeAtomicSdkError : FfiConverterRustBuffer<AtomicSdkException> {
    override fun read(buf: ByteBuffer): AtomicSdkException {
        
            return when(buf.getInt()) {
            1 -> AtomicSdkException.Failed(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
